import Dispatch
final class BookCaption {
    private let queue = DispatchQueue(label: "book.caption")
    private var title = "Без названия"
    func setTitle(_ value: String) { queue.sync { title = value } }
    func readTitle() -> String { queue.sync { title } }
}
let caption = BookCaption()
caption.setTitle("Тихий город")
print(caption.readTitle())

Вывод «Тихий город». readTitle возвращает завершённый результат, а не ещё не выполненную async-работу. Методы вызываются снаружи приватной очереди.
